-- Brings the Team page content back for a database that already ran the earlier cleanup.
-- Safe to run more than once: nothing is added twice.

UPDATE `team_members` SET `is_active` = 1;

-- The other team members' portfolio entries (as they were in the original seed data)
INSERT INTO `member_portfolios` (`member_id`, `title`, `slug`, `category`, `client`, `role_in_project`, `summary`, `description`, `image_url`, `project_url`, `tech_stack`, `completion_date`, `is_featured`, `sort_order`)
SELECT * FROM (SELECT 2 AS `member_id`, 'Cheetah Obsidian UI/UX Design System' AS `title`, 'cheetah-design-system' AS `slug`, 'Product Design' AS `category`, 'Creatsify Studio' AS `client`, 'Lead UI/UX Designer' AS `role_in_project`, 'Crafted a dark-mode obsidian design system with high-contrast accessibility tokens and 3D glass widgets.' AS `summary`, 'Constructed 250+ atomic Figma components, telemetry chart layouts, and interactive mobile driver interfaces.' AS `description`, '/assets/images/cheetah-showcase.jpg' AS `image_url`, 'https://creatsify.tech' AS `project_url`, 'Figma, Design Tokens, CSS Variables' AS `tech_stack`, '2026' AS `completion_date`, 1 AS `is_featured`, 1 AS `sort_order`) AS new_row
WHERE NOT EXISTS (SELECT 1 FROM `member_portfolios` WHERE `member_id` = 2 AND `slug` = 'cheetah-design-system');

INSERT INTO `member_portfolios` (`member_id`, `title`, `slug`, `category`, `client`, `role_in_project`, `summary`, `description`, `image_url`, `project_url`, `tech_stack`, `completion_date`, `is_featured`, `sort_order`)
