INSERT INTO `member_portfolios` (`member_id`, `title`, `slug`, `category`, `client`, `role_in_project`, `summary`, `description`, `image_url`, `project_url`, `tech_stack`, `completion_date`, `is_featured`, `sort_order`)
SELECT * FROM (SELECT 3 AS `member_id`, 'Cheetah Rider & Driver Companion' AS `title`, 'cheetah-rider-companion' AS `slug`, 'Mobile Development' AS `category`, 'Courier Fleet' AS `client`, 'Lead Mobile Developer' AS `role_in_project`, 'Native Flutter mobile app for delivery couriers featuring offline signature ePOD and background GPS tracking.' AS `summary`, 'Implemented background geofencing, thermal Bluetooth barcode scanner integrations, and instantaneous route recalculations.' AS `description`, '/assets/images/cheetah-showcase.jpg' AS `image_url`, 'https://creatsify.tech' AS `project_url`, 'Flutter, Dart, SQLite, Google Maps SDK' AS `tech_stack`, '2026' AS `completion_date`, 1 AS `is_featured`, 1 AS `sort_order`) AS new_row
