INSERT INTO `member_portfolios` (`member_id`, `title`, `slug`, `category`, `client`, `role_in_project`, `summary`, `description`, `image_url`, `project_url`, `tech_stack`, `completion_date`, `is_featured`, `sort_order`)
SELECT * FROM (SELECT 3 AS `member_id`, 'Flavor Fleet Multi-Vendor Food App' AS `title`, 'flavor-fleet-mobile' AS `slug`, 'Mobile App' AS `category`, 'Food Startup' AS `client`, 'Flutter Engineer' AS `role_in_project`, 'Customer-facing food ordering app with live delivery route animations and payment gateways.' AS `summary`, 'Created a seamless multi-restaurant browsing experience with category filters, cart persistence, and order tracking.' AS `description`, '/assets/images/restromaster-preview.jpg' AS `image_url`, 'https://creatsify.tech' AS `project_url`, 'Flutter, Dart, Firebase, Stripe SDK' AS `tech_stack`, '2026' AS `completion_date`, 1 AS `is_featured`, 2 AS `sort_order`) AS new_row
